node -e "
const fs=require('fs'),path=require('path');
const vi=JSON.parse(fs.readFileSync('messages/vi.json','utf8'));
const en=JSON.parse(fs.readFileSync('messages/en.json','utf8'));
function has(obj,p){return p.split('.').reduce((a,k)=>(a==null?undefined:a[k]),obj)!==undefined;}
const roots=['src/app/organizer'];
let files=[];
(function walk(d){for(const e of fs.readdirSync(d,{withFileTypes:true})){const p=path.join(d,e.name);if(e.isDirectory())walk(p);else if(/\.(tsx|ts)$/.test(e.name))files.push(p);}})(roots[0]);
// find translation namespaces used
const ns={};
for(const f of files){
  const src=fs.readFileSync(f,'utf8');
  for(const m of src.matchAll(/useTranslations\(\s*['\\\`]([^'\\\`]+)['\\\`]/g)){(ns[m[1]]??=new Set()).add(f);}
}
console.log('namespaces used in organizer:',Object.entries(ns).map(([k,v])=>k+' ('+v.size+' files)').join(', '));
// collect key usages:  translate('a.b.c') or t('a.b.c') scoped by nearest useTranslations ns (approx: file-level single ns)
const missing={};
for(const f of files){
  const src=fs.readFileSync(f,'utf8');
  const nsList=[...ns).filter(n=>src.includes(\"'\"+n+\"'\")||src.includes('\`'+n+'\`'));
  const fileNs=nsList.length===1?nsList[0]:null;
  for(const m of src.matchAll(/\b(?:translate|t|tr)\(\s*'([^']+)'/g)){
    const key=m[1];
    const cand=[];
    if(fileNs) cand.push(fileNs+'.'+key);
    cand.push(key);
    const ok=cand.some(c=>has(vi,c));
    if(!ok){ (missing[fileNs||'?']??=[]).push(f+' :: '+key); }
  }
}
const total=Object.values(missing).reduce((a,b)=>a+b.length,0);
console.log('POSSIBLY MISSING KEYS:',total);
for(const [k,v] of Object.entries(missing)){ if(!k||k==='?')continue; console.log('--- ns '+k+' ---'); [...new Set(v)].slice(0,40).forEach(x=>console.log('   '+x)); }
const unk=missing['?']||[];
if(unk.length){console.log('--- unresolved-ns ---'); [...new Set(unk)].slice(0,60).forEach(x=>console.log('   '+x));}
"

